#!/usr/bin/env bash
set -euo pipefail

npm install -g @google/gemini-cli@0.62.0

# Keep the installed CLI version stable when it starts interactively.
# System settings are outside the activity files; retain any existing settings.
sudo install -d /etc/gemini-cli
sudo python3 - <<'PY'
import json
import os
from pathlib import Path
import tempfile

path = Path('/etc/gemini-cli/settings.json')
settings = json.loads(path.read_text()) if path.exists() else {}
if not isinstance(settings, dict):
    raise ValueError('Gemini system settings must be a JSON object.')
general = settings.setdefault('general', {})
if not isinstance(general, dict):
    raise ValueError('Gemini general settings must be a JSON object.')
general['enableAutoUpdate'] = False
general['enableAutoUpdateNotification'] = False
fd, temporary = tempfile.mkstemp(dir=path.parent, prefix='.settings-')
try:
    with os.fdopen(fd, 'w') as handle:
        json.dump(settings, handle, indent=2)
        handle.write('\n')
    os.chmod(temporary, 0o644)
    os.replace(temporary, path)
finally:
    if os.path.exists(temporary):
        os.unlink(temporary)
PY

test "$(gemini --version)" = "0.62.0"

# Install a manual file saver outside the activity project. No automatic capture.
python3 - <<'FILE_SAVER_SETUP'
import base64, io, os, zipfile
from pathlib import Path
payload = ""
folder = Path.home() / 'study-tools'
folder.mkdir(mode=0o700, exist_ok=True)
with zipfile.ZipFile(io.BytesIO(base64.b64decode(payload))) as archive:
    for name in ('capture_state.py', 'verify_capture.py', 'session_capture.py'):
        path = folder / name
        path.write_bytes(archive.read(name))
        os.chmod(path, 0o600)
FILE_SAVER_SETUP
sudo tee /usr/local/bin/save-project >/dev/null <<'FILE_SAVER_COMMAND'
#!/usr/bin/env bash
set -euo pipefail
exec python3 "$HOME/study-tools/session_capture.py" "$@"
FILE_SAVER_COMMAND
sudo chmod 755 /usr/local/bin/save-project

